<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Atraso; use App\Models\Turma; use Illuminate\Http\Request; use Barryvdh\DomPDF\Facade\Pdf;
class RelatorioController extends Controller { private function query(Request $r){return Atraso::query()->when($r->data1,fn($q)=>$q->whereDate('data','>=',$r->data1))->when($r->data2,fn($q)=>$q->whereDate('data','<=',$r->data2))->when($r->turma,fn($q)=>$q->where('turma',$r->turma));} public function index(Request $r){$atrasos=$this->query($r)->orderBy('data')->paginate(20)->withQueryString();$turmas=Turma::orderBy('turma')->get();return view('admin.relatorios.index',compact('atrasos','turmas'));} public function pdf(Request $r){$atrasos=$this->query($r)->orderBy('data')->get();return Pdf::loadView('admin.relatorios.pdf',compact('atrasos'))->setPaper('a4','landscape')->stream('relatorio-atrasos.pdf');} public function totais(){return view('admin.relatorios.totais',['totais'=>Atraso::selectRaw('turma, count(*) total')->groupBy('turma')->orderByDesc('total')->get()]);} public function totaisPdf(){ $totais=Atraso::selectRaw('turma, count(*) total')->groupBy('turma')->orderByDesc('total')->get();return Pdf::loadView('admin.relatorios.totais-pdf',compact('totais'))->stream('total-atrasos-por-turma.pdf');}}
